//! Original prefab navigation over the SAME immutable native type/callable facts.
//! No parser, path table, interning or source/completion authority is introduced.
use dm_ir::{PackedU128,SymbolId,Resolver,ResolveQuery as Q,ResolvedMeaning as M};
use dm_tree::SemanticTree;
fn root(path:&str)->&str{if path=="/"{""}else{path}}
fn child_of(path:&str,parent:&str,name:&str)->bool{let Some((owner,leaf))=path.rsplit_once('/')else{return false};leaf==name&&owner==root(parent)}
fn below(path:&str,parent:&str)->bool{path.strip_prefix(root(parent)).is_some_and(|suffix|suffix.starts_with('/'))}
fn child<E:From<String>+From<&'static str>>(tree:&SemanticTree,parent:SymbolId,name:&str,poll:&mut impl FnMut()->Result<(),E>)->Result<Option<SymbolId>,E>{let parent=tree.symbols().text(parent).ok_or("prefab lexical parent spelling absent")?;let mut found=None;for node in tree.types(){poll()?;let path=tree.symbols().text(node.path).ok_or("prefab lexical candidate spelling absent")?;if child_of(path,parent,name){if found.replace(node.path).is_some(){return Err("prefab lexical child duplicated".into())}}}Ok(found)}
fn navigate<E:From<String>+From<&'static str>>(tree:&SemanticTree,parent:SymbolId,op:u8,name:&str,poll:&mut impl FnMut()->Result<(),E>)->Result<Option<SymbolId>,E>{
 poll()?;if op==b'/'{return child(tree,parent,name,poll)}
 if op==b'.'{let mut path=tree.symbols().text(parent).ok_or("prefab lexical owner spelling absent")?;loop{poll()?;let owner=if path.is_empty(){SymbolId::of("/")}else{SymbolId::of(path)};if let Some(found)=child(tree,owner,name,poll)?{return Ok(Some(found))}if path.is_empty()||path=="/"{return Ok(None)}path=path.rsplit_once('/').ok_or("prefab owner has no lexical parent")?.0;}}
 if op==b':'{if let Some(found)=child(tree,parent,name,poll)?{return Ok(Some(found))}let parent=tree.symbols().text(parent).ok_or("prefab downward owner spelling absent")?;let mut best:Option<(SymbolId,&str)>=None;for node in tree.types(){poll()?;let path=tree.symbols().text(node.path).ok_or("prefab downward candidate spelling absent")?;if let Some((candidate_parent,leaf))=path.rsplit_once('/'){if leaf==name&&below(path,parent){if best.is_none_or(|(_,old_parent)|candidate_parent.split('/').cmp(old_parent.split('/')).is_lt()){best=Some((node.path,candidate_parent));}}}}return Ok(best.map(|(id,_)|id))}
 Err("prefab path operator is not primary slash/dot/colon".into())
}
/// The caller lends an actual primary TypePath and its issued lexical owner.
/// Missing is a value-domain fact; caller must preserve original path error.
pub(crate) fn value_using<E:From<String>+From<&'static str>>(tree:&SemanticTree,resolver:&(impl Resolver+?Sized),profile:PackedU128,owner:SymbolId,path:&str,poll:&mut impl FnMut()->Result<(),E>)->Result<Option<SymbolId>,E>{
 poll()?;if resolver.source_owner()!=Resolver::source_owner(tree){return Err("prefab resolver belongs to another native source tree".into())}tree.validate_checker_builtin_profile(profile).map_err(|error|format!("prefab actual builtin profile: {error:?}"))?;let mut current=if path.starts_with('/'){SymbolId::of("/")}else{owner};let mut at=0;
 while at<path.len(){poll()?;let op=path.as_bytes()[at];if !matches!(op,b'/'|b'.'|b':'){return Err("prefab primary separator unavailable".into())}at+=1;let end=path[at..].find(['/', '.', ':']).map_or(path.len(),|next|at+next);let name=&path[at..end];if name.is_empty(){return Err("prefab primary component unavailable".into())}at=end;
  if matches!(name,"proc"|"verb"){if at==path.len(){return Ok(Some(current))}at+=1;let end=path[at..].find(['/', '.', ':']).map_or(path.len(),|next|at+next);let name=&path[at..end];if name.is_empty(){return Err("prefab primary callable name unavailable".into())}let fact=crate::checker_call_facts::callable_any_using(tree,resolver,profile,current,SymbolId::of(name),poll)?;return Ok(fact.owner());}
  let Some(next)=navigate(tree,current,op,name,poll)?else{return Ok(None)};let query=Q::Type(next);let actual=Resolver::resolve(tree,query);if actual!=M::Symbol(next)||resolver.resolve(query)!=actual{return Err("prefab native type query differs from immutable source".into())}current=next;
 }poll()?;Ok(Some(current))
}

#[cfg(test)]#[path="../examples/support/reference_hierarchy.rs"]mod reference_hierarchy;
#[cfg(test)]mod tests{
 use super::*;use dm_preprocess::{AcquiredSource,SourceProvider,SourceText};use std::path::Path;
 struct Source(AcquiredSource);impl SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Err("actual original acquisition required".into())}fn acquired_source(&self,_:&Path)->Result<Option<AcquiredSource>,String>{Ok(Some(self.0.clone()))}fn source_acquisition(&self,_:&Path,text:&SourceText)->Option<AcquiredSource>{self.0.lease().source_text().same_view(text).then(||self.0.clone())}}
 #[test]fn original_prefab_navigation_uses_lexical_parents_direct_child_priority_and_typed_control(){let source="/datum/nav/target\n/datum/nav/a/target\n/datum/nav/a/leaf\n    parent_type=/datum\n/datum/nav/down/a/target\n/datum/nav/down/a/a/target\n/datum/nav/down/z/target\n";let seed=reference_hierarchy::seed();let front=dm_tree::frontend::build_with_config(Path::new("prefab-value.dme"),&Source(AcquiredSource::from_original_bytes(source.as_bytes().to_vec(),())),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None}).unwrap();let tree=&*front.snapshot.tree;let profile=tree.checker_builtin_profile().unwrap();for(owner,path,wanted)in[("/datum/nav",":target","/datum/nav/target"),("/datum/nav/down",":target","/datum/nav/down/a/target"),("/datum/nav/a/leaf",".target","/datum/nav/a/target"),("/datum/nav/a/leaf","/datum/nav/target","/datum/nav/target")]{assert_eq!(value_using(tree,tree,profile,SymbolId::of(owner),path,&mut||Ok::<_,String>(())).unwrap(),Some(SymbolId::of(wanted)));}let count=std::cell::Cell::new(0);let error=value_using(tree,tree,profile,SymbolId::of("/datum/nav/down"),":target",&mut||{count.set(count.get()+1);if count.get()==4{Err(crate::policy_body_demand::PolicyFailure::Operational(std::io::Error::from_raw_os_error(1450)))}else{Ok(())}}).unwrap_err();assert_eq!(count.get(),4);assert!(matches!(error,crate::policy_body_demand::PolicyFailure::Operational(error)if error.raw_os_error()==Some(1450)));}
}
